INSERT INTO xxl_ai_todo_thread (
	user_id, title, pending, evaluating, expired, subscriptions, last_time, add_time, update_time
) VALUES (
	#{userId}, #{title}, #{pending}, #{evaluating}, #{expired}, #{subscriptions}, #{lastTime}, NOW(), NOW()
)

mapper.select:
SELECT 
FROM xxl_ai_todo_thread AS t
WHERE t.id = #{id}

SELECT 
FROM xxl_ai_todo_thread AS t
WHERE t.user_id = #{userId}
ORDER BY t.last_time DESC, t.id DESC
LIMIT #{offset}, #{pagesize}

SELECT count(1)
FROM xxl_ai_todo_thread AS t
WHERE t.user_id = #{userId}
